        let result = tokio::select! {
            biased;
            _ = cancel.cancelled() => {
                return Err(ToolError::Other(anyhow::anyhow!(
                    "MCP tool call `{}` cancelled",
                    self.name
                )));
            }
            r = call => r,
        };
        let result = result.map_err(|e| ToolError::Other(anyhow::Error::from(e)))?;
