1	//! `McpTool` — adapts a remote MCP tool to core's `Tool<Ctx>` trait.
2	
3	use std::marker::PhantomData;
4	use std::sync::LazyLock;
5	
6	use async_trait::async_trait;
7	use paigasus_helikon_core::{Tool, ToolContext, ToolEffect, ToolError, ToolOutput};
8	use rmcp::model::CallToolResult;
9	
10	use crate::client::handle::McpServerHandle;
11	
12	/// Map an MCP `CallToolResult` into core's `ToolOutput`/`ToolError`.
13	///
14	/// - `is_error == Some(true)` → `ToolError::Other` carrying the text content.
15	/// - `structured_content` (when present) becomes `ToolOutput.content` as-is.
16	/// - Otherwise a single text content becomes a JSON string; anything else is
17	///   serialized as a JSON array of content blocks.
18	pub(crate) fn map_call_result(result: CallToolResult) -> Result<ToolOutput, ToolError> {
19	    if result.is_error == Some(true) {
20	        // Known gap: a structured_error result also carries
21	        // structured_content; today only the text rendering reaches the
22	        // model. Surface the structured value if a real server needs it
23	        // (file a follow-up ticket when one does).
24	        let msg = content_text(&result.content);
25	        return Err(ToolError::Other(anyhow::anyhow!(
26	            "MCP tool returned an error: {msg}"
27	        )));
28	    }
29	    if let Some(v) = result.structured_content {
30	        return Ok(ToolOutput::new(v));
31	    }
32	    let content = result.content;
33	    if content.len() == 1 && content[0].as_text().is_some() {
34	        let text = content.into_iter().next().unwrap();
35	        // SAFETY: guarded by `as_text().is_some()` above.
36	        let rmcp::model::RawContent::Text(t) = text.raw else {
37	            unreachable!()
38	        };
39	        return Ok(ToolOutput::new(serde_json::Value::String(t.text)));
40	    }
41	    let arr =
42	        serde_json::to_value(&content).map_err(|e| ToolError::Other(anyhow::Error::from(e)))?;
43	    Ok(ToolOutput::new(arr))
44	}
45	
46	/// Concatenate the text parts of a content vec for error messages.
47	fn content_text(content: &[rmcp::model::Content]) -> String {
48	    let parts: Vec<&str> = content
49	        .iter()
50	        .filter_map(|c| c.as_text().map(|t| t.text.as_str()))
51	        .collect();
52	    if parts.is_empty() {
53	        "<no text content>".to_owned()
54	    } else {
55	        parts.join("\n")
56	    }
57	}
58	
59	/// Placeholder schema advertised by lazy-mode tools.
60	static PLACEHOLDER_SCHEMA: LazyLock<serde_json::Value> =
61	    LazyLock::new(|| serde_json::json!({ "type": "object", "additionalProperties": true }));
62	
63	/// A remote MCP tool adapted to core's [`Tool`].
64	///
65	/// `Ctx` is a phantom: MCP tools never read the user context, so one handle
66	/// serves agents of any context type. `ToolEffect::Write` is never produced —
67	/// server-declared annotations are untrusted metadata and must not unlock
68	/// `AcceptEdits` auto-approval; `read_only_hint == true` maps to `ReadOnly`,
69	/// everything else to `SideEffect`.
70	pub struct McpTool<Ctx> {
71	    handle: McpServerHandle,
72	    wire_name: String,
73	    name: String,
74	    description: String,
75	    schema: serde_json::Value,
76	    output_schema: Option<serde_json::Value>,
77	    effect: ToolEffect,
78	    _ctx: PhantomData<fn() -> Ctx>,
79	}
80	
81	impl<Ctx> McpTool<Ctx> {
82	    pub(crate) fn new(handle: McpServerHandle, tool: &rmcp::model::Tool, lazy: bool) -> Self {
83	        let wire_name = tool.name.to_string();
84	        let name = handle.prefixed(&wire_name);
85	        let mut description = tool.description.as_deref().unwrap_or_default().to_owned();
86	        let schema = if lazy {
87	            let hint = format!(
88	                "(Full input schema available via the `{}` tool.)",
89	                handle.prefixed("search_tools")
90	            );
91	            if !description.is_empty() {
92	                description.push(' ');
93	            }
94	            description.push_str(&hint);
95	            PLACEHOLDER_SCHEMA.clone()
96	        } else {
97	            serde_json::Value::Object((*tool.input_schema).clone())
98	        };
99	        let output_schema = if lazy {
100	            None
101	        } else {
102	            tool.output_schema
103	                .as_ref()
104	                .map(|s| serde_json::Value::Object((**s).clone()))
105	        };
106	        let effect = match &tool.annotations {
107	            Some(a) if a.read_only_hint == Some(true) => ToolEffect::ReadOnly,
108	            _ => ToolEffect::SideEffect,
109	        };
110	        Self {
111	            handle,
112	            wire_name,
113	            name,
114	            description,
115	            schema,
116	            output_schema,
117	            effect,
118	            _ctx: PhantomData,
119	        }
120	    }
121	}
122	
123	#[async_trait]
124	impl<Ctx> Tool<Ctx> for McpTool<Ctx>
125	where
126	    Ctx: Send + Sync + 'static,
127	{
128	    fn name(&self) -> &str {
129	        &self.name
130	    }
131	
132	    fn description(&self) -> &str {
133	        &self.description
134	    }
135	
136	    fn schema(&self) -> &serde_json::Value {
137	        &self.schema
138	    }
139	
140	    fn output_schema(&self) -> Option<&serde_json::Value> {
141	        self.output_schema.as_ref()
142	    }
143	
144	    fn effect(&self) -> ToolEffect {
145	        self.effect
146	    }
147	
148	    async fn invoke(
149	        &self,
150	        ctx: &ToolContext<Ctx>,
151	        args: serde_json::Value,
152	    ) -> Result<ToolOutput, ToolError> {
153	        let arguments = match args {
154	            serde_json::Value::Object(map) => Some(map),
155	            serde_json::Value::Null => None,
156	            other => {
157	                return Err(ToolError::InvalidArgs {
158	                    schema_errors: vec![format!(
159	                        "MCP tools take a JSON object as arguments, got: {other}"
160	                    )],
161	                })
162	            }
163	        };
164	        // Race the remote call against the run's cancellation token: rmcp's
165	        // `call_tool` waits indefinitely, so a hung MCP server must not hang
166	        // the whole agent run past a cancel.
167	        let cancel = ctx.cancel().clone();
168	        let call = self.handle.call_tool_raw(&self.wire_name, arguments);
169	        let result = tokio::select! {
170	            biased;
171	            _ = cancel.cancelled() => {
172	                return Err(ToolError::Other(anyhow::anyhow!(
173	                    "MCP tool call `{}` cancelled",
174	                    self.name
175	                )));
176	            }
177	            r = call => r,
178	        };
179	        let result = result.map_err(|e| ToolError::Other(anyhow::Error::from(e)))?;
180	        map_call_result(result)
181	    }
182	}
